package com.suarez.pedido; import org.springframework.cloud.openfeign.FeignClient;import org.springframework.web.bind.annotation.*; @FeignClient(name="cliente-service",fallback=ClienteFallback.class) interface ClienteClient{@GetMapping("/api/clientes/{id}") ClienteDTO get(@PathVariable long id);} @FeignClient(name="producto-service",fallback=ProductoFallback.class) interface ProductoClient{@GetMapping("/api/productos/{id}") ProductoDTO get(@PathVariable long id);} record ClienteDTO(Long id,String nombre,String apellido,String direccion,String nroDni,String estado){} record ProductoDTO(Long id,String nombre,double precio,int stock,Long categoriaId,CategoriaDTO categoria){} record CategoriaDTO(Long id,String nombre,String estado){}
